WITH sample AS MATERIALIZED (
    SELECT * FROM public.chat_messages TABLESAMPLE SYSTEM (0.08) REPEATABLE (7102026) LIMIT 20000
  ) SELECT jsonb_build_object('table','chat_messages','sample_seed',7102026,'sample_rows',count(*),
    'actual_tuple_bytes',avg(pg_column_size(s)),
    'actual_aligned_bytes',avg(ceil(pg_column_size(s)/8.0)*8+4),
    'original_aligned_bytes',avg(ceil(pg_column_size(ROW(twitch_message_id,broadcaster_user_id,twitch_stream_id,chatter_user_id,chatter_login,source,sent_at,received_at,message_type,raw_text,badges,emotes,reply_parent_message_id,shared_chat_source_channel_id,deleted_at,cleared_at,raw_irc_message_id,raw_eventsub_event_id,created_at,updated_at))/8.0)*8+4),
    'keys_aligned_bytes',avg(ceil(pg_column_size(ROW(twitch_message_id,CASE WHEN broadcaster_user_id IS NOT NULL THEN 1::int END,CASE WHEN twitch_stream_id IS NOT NULL THEN 1::int END,CASE WHEN chatter_user_id IS NOT NULL THEN 1::int END,chatter_login,source,sent_at,received_at,message_type,raw_text,badges,emotes,reply_parent_message_id,CASE WHEN shared_chat_source_channel_id IS NOT NULL THEN 1::int END,deleted_at,cleared_at,raw_irc_message_id,raw_eventsub_event_id,created_at,updated_at))/8.0)*8+4),
    'compact_aligned_bytes',avg(ceil(pg_column_size(ROW(sent_at,received_at,deleted_at,cleared_at,CASE WHEN NOT coalesce((isfinite(created_at) AND isfinite(received_at) AND (CASE WHEN isfinite(created_at) AND isfinite(received_at) THEN extract(epoch FROM (created_at-received_at))*1000000 END) BETWEEN -2147483648 AND 2147483647),false) THEN created_at END,CASE WHEN NOT coalesce((isfinite(updated_at) AND isfinite(created_at) AND (CASE WHEN isfinite(updated_at) AND isfinite(created_at) THEN extract(epoch FROM (updated_at-created_at))*1000000 END) BETWEEN -2147483648 AND 2147483647),false) THEN updated_at END,CASE WHEN broadcaster_user_id IS NOT NULL THEN 1::int END,CASE WHEN twitch_stream_id IS NOT NULL THEN 1::int END,CASE WHEN chatter_user_id IS NOT NULL THEN 1::int END,CASE WHEN chatter_login IS NOT NULL THEN 1::int END,CASE WHEN shared_chat_source_channel_id IS NOT NULL THEN 1::int END,raw_irc_message_id,raw_eventsub_event_id,CASE WHEN (isfinite(created_at) AND isfinite(received_at) AND (CASE WHEN isfinite(created_at) AND isfinite(received_at) THEN extract(epoch FROM (created_at-received_at))*1000000 END) BETWEEN -2147483648 AND 2147483647) THEN nullif((CASE WHEN isfinite(created_at) AND isfinite(received_at) THEN extract(epoch FROM (created_at-received_at))*1000000 END)::int,0) END,CASE WHEN (isfinite(updated_at) AND isfinite(created_at) AND (CASE WHEN isfinite(updated_at) AND isfinite(created_at) THEN extract(epoch FROM (updated_at-created_at))*1000000 END) BETWEEN -2147483648 AND 2147483647) THEN nullif((CASE WHEN isfinite(updated_at) AND isfinite(created_at) THEN extract(epoch FROM (updated_at-created_at))*1000000 END)::int,0) END,twitch_message_id,nullif(source,'irc'),nullif(message_type,'privmsg'),raw_text,nullif(badges,decode('00','hex')),nullif(emotes,decode('00','hex')),reply_parent_message_id))/8.0)*8+4)
    , 'updated_equals_created_fraction',avg((updated_at=created_at)::int)
    , 'created_equals_received_fraction',avg((created_at=received_at)::int)

  ) FROM sample s;
